// Pure filter helper: keep names containing the query, case-insensitively.
// Empty/whitespace-only query returns the list unchanged.
function filterNames(names, query) {
  const needle = String(query == null ? '' : query).trim().toLowerCase();
  if (needle === '') return names.slice();
  return names.filter((name) => name.toLowerCase().includes(needle));
}

// Dual environment: browser (script tag, no module) + node tests (require).
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { renderList, filterNames };
