const NAMES = ['Alice Johnson', 'Boris Petrov', 'Carol Nguyen', 'David Okafor'];

test('filterNames matches case-insensitively', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'car'), ['Carol Nguyen']);
  assert.deepStrictEqual(filterNames(NAMES, 'CAROL'), ['Carol Nguyen']);
});

test('filterNames matches a substring anywhere in the name', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'ov'), ['Boris Petrov']);
  assert.deepStrictEqual(filterNames(NAMES, 'o'), [
    'Alice Johnson',
    'Boris Petrov',
    'David Okafor',
  ]);
});

test('filterNames with empty or whitespace query returns all names', () => {
  assert.deepStrictEqual(filterNames(NAMES, ''), NAMES);
  assert.deepStrictEqual(filterNames(NAMES, '   '), NAMES);
  assert.deepStrictEqual(filterNames(NAMES, null), NAMES);
});

test('filterNames trims surrounding whitespace in the query', () => {
  assert.deepStrictEqual(filterNames(NAMES, '  boris  '), ['Boris Petrov']);
});

test('filterNames returns empty array when nothing matches', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'zzz'), []);
});

test('filterNames does not mutate the input array', () => {
  const input = NAMES.slice();
  filterNames(input, 'a');
  assert.deepStrictEqual(input, NAMES);
});

