3	// The string "gym-fixture" is deliberate: stop it with `pkill -f gym-fixture`.
4	const http = require('http');
5	const fs = require('fs');
6	const path = require('path');
7	
8	const DIST = path.join(__dirname, 'dist');
9	const PORT = 4173;
10	const TYPES = {
11	  '.html': 'text/html; charset=utf-8',
12	  '.js': 'text/javascript; charset=utf-8',
13	  '.css': 'text/css; charset=utf-8',
14	};
15	
16	const server = http.createServer((req, res) => {
17	  const urlPath = decodeURIComponent((req.url || '/').split('?')[0]);
18	  const rel = urlPath.endsWith('/') ? `${urlPath}index.html` : urlPath;
19	  const file = path.normalize(path.join(DIST, rel));
20	  if (!file.startsWith(DIST + path.sep)) {
21	    res.writeHead(403);
22	    res.end('forbidden');
23	    return;
24	  }
25	  fs.readFile(file, (err, data) => {
26	    if (err) {
27	      res.writeHead(404);
28	      res.end('not found');
29	      return;
30	    }
31	    res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream' });
32	    res.end(data);
33	  });
34	});
35	
36	server.listen(PORT, () => console.log(`gym-fixture-server on ${PORT}`));
